public void delete()
{
    LedgerAllocationRuleSource  childRuleSource;
    delete_from childRuleSource where childRuleSource.ruleId == this.RuleID && childruleSource.AVAParentLineNum == this.LineNum;

    next delete();

    if(FormDataUtil::isFormDataSource(this))
    {
        FormDataUtil::getFormDataSource(this).research(true);
    }
}

public void insert()
{
    next insert();
    this.insertSumAccountsLine();
    if(FormDataUtil::isFormDataSource(this))
    {
        FormDataUtil::getFormDataSource(this).research(true);
    }

}

public void update()
{
    LineNum parentLineNum = this.orig().LineNum;
    LedgerAllocationRuleSource childruleSource;
    LedgerAllocationRuleID  ruleId = this.RuleID;

    next update();
    if (LedgerAllocationRuleSource::existChild(RuleID, parentLineNum))
    {
        ttsbegin;
        select forupdate firstonly childRuleSource where childruleSource.RuleID == ruleId
                                                    && childruleSource.AVAParentLineNum == parentLineNum;
        if (childruleSource)
        {
            childRuleSource.SourceCriteria  = LedgerAllocationRuleSource::AccountNumbersFromSumAccount(this.SourceCriteria);
            childRuleSource.AVAParentLineNum = this.LineNum;
            childRuleSource.doupdate();
        }
        ttscommit;
    }
    else
    {
        this.insertSumAccountsLine();
    }
    if(FormDataUtil::isFormDataSource(this))
    {
        FormDataUtil::getFormDataSource(this).research(true);
    }
}

/// <summary>
/// AVA
/// </summary>
public void insertSumAccountsLine()
{
    LedgerAllocationRuleSource  newAccountRecord;

    if (this.FieldSetting == LedgerAllocationAccountDimension::SumAccount)
    {
        ttsbegin;
        newAccountRecord.RuleID             = this.RuleID;
        newAccountRecord.FieldSetting       = LedgerAllocationAccountDimension::Account;
        newAccountRecord.LineNum            = LedgerAllocationRuleSources::lastSourceLineNum(this.RuleID) + 1;
        newAccountRecord.SourceCriteria     = LedgerAllocationRuleSource::AccountNumbersFromSumAccount(this.SourceCriteria);
        newAccountRecord.AVAParentLineNum   = this.LineNum;
        newAccountRecord.insert();
        ttscommit;
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_ruleID">LedgerAllocationRuleID</param>
/// <param name = "_parentLineNum">LineNum</param>
/// <returns>boolean</returns>
public static boolean existChild(LedgerAllocationRuleID _ruleID, LineNum _parentLineNum)
{
    LedgerAllocationRuleSource ledgerAllocationRuleSource;

    return (select firstonly RecId from ledgerAllocationRuleSource
                where ledgerAllocationRuleSource.RuleID == _ruleID &&
                    ledgerAllocationRuleSource.AVAParentLineNum == _parentLineNum).RecId != 0;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_ruleID">LedgerAllocationRuleID</param>
/// <param name = "_parentLineNum">LineNum</param>
/// <param name = "_forupdate">boolean</param>
/// <returns>LedgerAllocationRuleSource</returns>
public static LedgerAllocationRuleSource findChild(
    LedgerAllocationRuleID _ruleID,
    LineNum _parentLineNum,
    boolean _forupdate = false)
{
    LedgerAllocationRuleSource ledgerAllocationRuleSource;

    ledgerAllocationRuleSource.selectForUpdate(_forupdate);

    select firstonly * from ledgerAllocationRuleSource
        where ledgerAllocationRuleSource.RuleID == _ruleID &&
            ledgerAllocationRuleSource.LineNum == _parentLineNum;

    return ledgerAllocationRuleSource;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_sumAccount">MainAccountNum</param>
/// <param name = "_accountNumbersFromSum">Description255</param>
/// <param name = "_usedAccounts">set(types::string)</param> 
/// <returns>Description255</returns>
public static DimensionsAccountCriteria AccountNumbersFromSumAccount(MainAccountNum _sumAccount, DimensionsAccountCriteria _accountNumbersFromSum = Global::strMin(), Set _usedAccounts = new Set(Types::String))
{
    DimensionsAccountCriteria                   ret = _accountNumbersFromSum;

    MainAccount                                 mainAccount, criteriaAccount;
    DimensionAttributeValueTotallingCriteria    totallingCriteria;
    DimensionAttributeValue                     dimensionAttributeValue;

    //Set                                         usedAccounts = new Set(Types::String);

    mainAccount = MainAccount::findByMainAccountId(_sumAccount);

    if (mainAccount.Type == DimensionLedgerAccountType::Total)
    {
        _usedAccounts.add(mainAccount.MainAccountId);
        while select totallingCriteria
            join criteriaAccount where criteriaAccount.MainAccountId >= totallingCriteria.FromValue
                && criteriaAccount.MainAccountId <= totallingCriteria.ToValue
        exists join dimensionAttributeValue
         where dimensionAttributeValue.RecId == totallingCriteria.DimensionAttributeValue
            && dimensionAttributeValue.DimensionAttribute == DimensionAttribute::getWellKnownDimensionAttribute(DimensionAttributeType::MainAccount)
            && dimensionAttributeValue.EntityInstance == mainAccount.RecId
        {
            if (criteriaAccount.Type == DimensionLedgerAccountType::Total && !_usedAccounts.in(criteriaAccount.MainAccountId))
            {
                ret = LedgerAllocationRuleSource::AccountNumbersFromSumAccount(criteriaAccount.MainAccountId, ret, _usedAccounts);
                _usedAccounts.add(criteriaAccount.MainAccountId);
            }
            else if (criteriaAccount.Type != DimensionLedgerAccountType::Total)
            {
                ret += ret ? "@NDX:NXAComma" : Global::strMin();
                ret += criteriaAccount.MainAccountId;
            }
        }

    }
    return ret;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_ctrl">FormStringControl</param>
public static void lookupSumMainAccounts(FormStringControl _ctrl)
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(MainAccount), _ctrl);
    Query                   lookupQuery;
    QueryBuildDataSource    qbds;

    lookupQuery = new Query();
    qbds = lookupQuery.addDataSource(tableNum(MainAccount));
    qbds.addRange(fieldNum(MainAccount, Type)).value(queryValue(DimensionLedgerAccountType::Total));
    MainAccount::addSecureRangeForChartOfAccounts(qbds);

    // Display the MainAccountId, Name, and Type fields in the lookup form.
    sysTableLookup.addLookupfield(fieldNum(MainAccount, MainAccountId));
    sysTableLookup.addLookupMethod(tableMethodStr(MainAccount, localizedName));
    sysTableLookup.addLookupfield(fieldNum(MainAccount, Type));

    sysTableLookup.parmQuery(lookupQuery);

    sysTableLookup.performFormLookup();
}
